mapper.select:
SELECT config_id, config_key, config_value, config_group, config_type, description, is_encrypted, is_system, sort_order, create_time, update_time
FROM sys_config
ORDER BY sort_order ASC;

mapper.update:
UPDATE sys_config
SET config_value = #{configValue}, update_time = CURRENT_TIMESTAMP
WHERE config_key = #{configKey};
